function adminPilotIntelligence(name,data){
  const index=['인구구조','지지구조','회복탄력','미디어','이슈','위험·기회','근거','전략'].map((x,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b>${x}</span>`).join('');
  const gate=adminGate({name,description:'허용 원자료와 JCS 해석을 분리한 단일 인물 파일럿 리포트 (JCS 해석)',status:'LIVE',statusMeta:data.snapshot});
  const executive=adminExecutive({classification:'SINGLE-PERSON PILOT',title:data.signal.label,body:data.diagnosis.body,evidenceValue:'3+1',evidenceNote:'공식·여론·뉴스 + 분석 모델',kpis:[{label:'정치 상태',value:'전환',note:'당대표 취임 국면'},{label:'공식 근거',value:'2',note:'선거·경선 결과'},{label:'외부 근거',value:String(data.sources.length),note:'출처·제외 근거 포함'},{label:'코호트',value:String(data.cohorts.length*2),note:'연령×성별 맥락지수'}],pulseTitle:data.diagnosis.title,pulseValue:String(data.signal.index),index});
  const cohorts=adminCohortRows(data);
  const supportItems=[{label:'핵심 지지층',value:data.support.core,note:'당원·정당 기반'},{label:'확장 지지층',value:data.support.expand,note:'중도·무당층 확장'},{label:'유동층',value:data.support.floating,note:'일반 여론 변동'},{label:'이탈 위험',value:data.support.risk,note:'갈등·성과 리스크'}];
  const qualityItems=[{label:'충성도',score:data.support.loyalty},{label:'행동성',score:data.support.action},{label:'안정성',score:data.support.stability},{label:'확장성',score:data.support.scalability}];
  const waterfall=data.support.waterfall.map(([label,value],index)=>`<article><span>0${index+1}</span><b>${esc(label)}</b><div><i style="width:${clamp(value*4)}%"></i></div><strong>+${value}</strong></article>`).join('');
  const recoveryPoints=data.resilience.curve.map((value,i)=>`${20+i*112},${118-clamp(value)}`).join(' '),recoveryArea=`20,118 ${recoveryPoints} ${20+(data.resilience.curve.length-1)*112},118`;
  const propagation=[['언론 도달',data.mediaScores.reach],['소셜 확산',data.mediaScores.social],['자발 전파',data.mediaScores.organic],['지속 노출',data.mediaScores.persistence]].map(([label,value],i)=>`<article style="--flow:${value}%"><span>0${i+1}</span><b>${label}</b><strong>${value}</strong><i></i></article>`).join('');
  const issuePoints=data.issues.map((item,index)=>`<article style="--issue-x:${item.impact}%;--issue-y:${100-item.persistence}%;--issue-size:${30+(index*4)}px"><i></i><div><b>${esc(item.title)}</b><span>${esc(item.kind)} · 영향 ${item.impact} · 지속 ${item.persistence}</span></div></article>`).join('');
  const gap=data.core[0].score-data.transition[2].score;
  const competitors=data.competitors.map((item,index)=>`<article><span>${index+1}</span><b>${esc(item.name)}</b><div><i style="width:${item.score}%"></i></div><strong>${item.score}</strong><small>${esc(item.note)}</small></article>`).join('');
  const strategy=data.strategies.map((item,index)=>`<article><span>${index<2?'7일':index<5?'14일':'30일'}</span><div><small>PRIORITY ${String(index+1).padStart(2,'0')}</small><b>${esc(item.title)}</b><p>${esc(item.body)}</p></div></article>`).join('');
  const newsSources=new Set(data.news.map(item=>item.source)).size;
  const historyPoints=data.trend.map((value,i)=>`${20+i*105},${110-value}`).join(' ');
  const evidence=sourceLedger(data.sources);
  return `<details class="admin-intelligence-report-shell jcs-private-intelligence-v3" data-design-system="jcs-private-intelligence-v3" data-visual-chapters="admin-pi-heatmap-chapter admin-pi-waterfall-chapter admin-pi-resilience-chapter admin-pi-propagation-chapter admin-pi-impact-chapter admin-pi-signal-board admin-pi-evidence-ledger admin-pi-strategy-roadmap">${gate}<div class="admin-intelligence-report-body">${executive}<div class="admin-political-intelligence admin-pi-report-main"><section class="admin-pi-report-block">${adminHead('AGE × GENDER MATRIX','연령·성별 관심 구조','한국갤럽 정당 맥락 + 환산지수')}<div class="admin-cohort-heatmap-v3"><header><span>연령</span><b>남성</b><b>여성</b></header>${cohorts}</div><p class="admin-pi-method-note">후보 개인의 실측 지지율이 아니라 정당·정치성향 자료를 정치인 맥락에 적용한 비교지수입니다.</p></section><section class="admin-pi-report-block">${adminHead('CORE SUPPORT DYNAMICS','핵심 지지 구조','공식 경선·선거 + 갤럽 맥락')}${adminBarRows(supportItems)}<div class="admin-support-waterfall-v3">${adminHead('SUPPORT WATERFALL','지지 이동 폭포','유입에서 유지까지의 증분')}${waterfall}</div><div class="admin-support-quality-v3">${adminHead('SUPPORT QUALITY','지지 품질','충성·행동·안정·확장')}${radarVisual(qualityItems,'admin-support-radar-v3','김민석 지지 품질 레이더 차트')}<div>${qualityItems.map(item=>`<span><b>${item.label}</b><strong>${item.score}</strong></span>`).join('')}</div></div></section><section class="admin-pi-report-block">${adminHead('POLITICAL RESILIENCE','정치적 회복탄력성','공식 이력·현재 역할 기반')}<div class="admin-resilience-area-v3"><svg viewBox="0 0 600 130" role="img" aria-label="김민석 정치적 회복탄력성"><line x1="20" y1="40" x2="580" y2="40"></line><line x1="20" y1="80" x2="580" y2="80"></line><polygon points="${recoveryArea}"></polygon><polyline points="${recoveryPoints}"></polyline></svg><aside><span>RESILIENCE INDEX</span><strong>${data.resilience.index}</strong><dl><div><dt>충격 저항</dt><dd>${data.resilience.resistance}</dd></div><div><dt>회복 속도</dt><dd>${data.resilience.speed}</dd></div><div><dt>회복 안정성</dt><dd>${data.resilience.stability}</dd></div></dl></aside></div></section><section class="admin-pi-report-block">${adminHead('MEDIA PROPAGATION','미디어 전파 구조','Google 뉴스 중심·API fallback 없음')}<div class="admin-propagation-flow-v3">${propagation}</div><p class="admin-visual-reading-v3">언론 도달 ${data.mediaScores.reach}이 가장 강하고 자발 전파 ${data.mediaScores.organic}에서 손실이 발생한다. 대형 보도 뒤 자발적으로 재사용될 수 있는 짧은 근거 콘텐츠가 필요하다.</p></section><section class="admin-pi-report-block">${adminHead('ISSUE IMPACT MAP','이슈 영향 지도','최근 보도 주제 분류')}<div class="admin-issue-quadrant-v3"><span class="x-axis">영향도 →</span><span class="y-axis">지속성 ↑</span>${issuePoints}</div></section><section class="admin-pi-report-block">${adminHead('RISK & OPPORTUNITY','위험·기회 신호','근거와 전략 우선순위')}<div class="admin-risk-matrix-v3"><section><header><b>RISK SIGNALS</b><span>위험</span></header>${data.risks.map((text,index)=>`<article><strong>R${index+1}</strong><p>${esc(text)}</p></article>`).join('')}</section><section><header><b>OPPORTUNITY SIGNALS</b><span>기회</span></header>${data.opportunities.map((text,index)=>`<article><strong>O${index+1}</strong><p>${esc(text)}</p></article>`).join('')}</section></div><div class="admin-gap-dumbbell-v3"><header><b>ATTENTION → SUPPORT GAP</b><span>${gap}p 격차</span></header><div><i style="left:${data.transition[2].score}%"></i><em style="left:${data.core[0].score}%"></em><span></span></div><footer><b>지지 전환 ${data.transition[2].score}</b><b>관심 ${data.core[0].score}</b></footer><p>높은 관심을 민생 성과 증거로 전환하는 것이 우선이다.</p></div><div class="admin-competitor-flow-v3">${adminHead('COMPETITOR FLOW','경쟁자 흐름','직접 맞대결 근거')}${competitors}</div></section><section class="admin-pi-report-block">${adminHead('EVIDENCE BASE','분석 근거','허용 범주·제외 범주 공개')}${evidence}</section><section class="admin-pi-report-block">${adminHead('JCS STRATEGIC SOLUTION','JCS 전략 솔루션','김민석 단일 파일럿')}<div class="admin-strategy-roadmap-v3">${strategy}</div><div class="admin-pi-conclusion"><div><span>STRATEGIC CONCLUSION</span><small>최종 전략 제안</small></div><strong>${esc(data.conclusion)}</strong></div></section>${searchPendingChapters()}<section class="admin-pi-report-block admin-derived-chapter-v3">${adminHead('NEWS NARRATIVE INTELLIGENCE','뉴스 서사 인텔리전스','Google 뉴스 6건·프레임 분류')}<div class="admin-news-narrative-v3"><article><small>수집 기사</small><strong>${data.news.length}</strong><span>건</span></article><article><small>고유 매체</small><strong>${newsSources}</strong><span>개</span></article><div>${data.issues.map(item=>`<span style="--frame:${item.impact}%"><b>${esc(item.title)}</b><i></i><strong>${item.impact}</strong></span>`).join('')}</div></div></section><section class="admin-pi-report-block admin-derived-chapter-v3">${adminHead('PUBLIC OPINION CONVERSION','여론 전환 구조','공식 경선·갤럽 맥락')}<div class="admin-opinion-conversion-v3"><article><b>당대표 최종</b><div><i style="width:${data.raw.leadership.finalRate}%"></i></div><strong>${data.raw.leadership.finalRate}%</strong></article><article><b>국민 여론조사</b><div><i style="width:${data.raw.leadership.publicPollRate}%"></i></div><strong>${data.raw.leadership.publicPollRate}%</strong></article><article><b>중도층 민주당</b><div><i style="width:${data.raw.gallup.moderateDemocratic}%"></i></div><strong>${data.raw.gallup.moderateDemocratic}%</strong></article></div><p class="admin-visual-reading-v3">조직 선택은 최종 승리로 연결됐지만 국민 여론조사에서는 경쟁 후보와 초접전이었다. 확장 메시지는 조직 결집과 별도로 관리해야 한다.</p></section><section class="admin-pi-report-block admin-derived-chapter-v3">${adminHead('CONSTITUENCY OPPORTUNITY','선거구 기회 분석','제22대 총선 공식 결과')}<div class="admin-constituency-opportunity-v3"><div><span>김민석</span><i style="width:${data.raw.election.voteRate}%"></i><strong>${data.raw.election.voteRate}%</strong></div><div><span>상대 후보</span><i style="width:${data.raw.election.opponentRate}%"></i><strong>${data.raw.election.opponentRate}%</strong></div><article><small>실제 득표</small><strong>${data.raw.election.votes.toLocaleString('ko-KR')}</strong><span>표</span></article><article><small>격차</small><strong>${data.raw.election.margin}</strong><span>%p</span></article></div><p class="admin-visual-reading-v3">1.15%p의 초접전 지역이다. 세부 연령×성별 지역구 인구 원본이 연결되면 결집 대상과 설득 대상을 인구 피라미드로 확장한다.</p></section><section class="admin-pi-report-block admin-derived-chapter-v3">${adminHead('JCS CROSS INTELLIGENCE','교차 인텔리전스','뉴스·경선·선거·코호트 교차')}<div class="admin-cross-intelligence-v3"><article><small>관심→지지 전환</small><strong>${data.transition[2].score}</strong><span>${gap}p 보완 필요</span></article><article><small>후보 개인 프리미엄</small><strong>+${(data.raw.leadership.finalRate-data.raw.leadership.publicPollRate).toFixed(2)}</strong><span>최종 결과−국민여론</span></article><article><small>미디어 도달</small><strong>${data.mediaScores.reach}</strong><span>자발 전파 ${data.mediaScores.organic}</span></article><article><small>외연 준비도</small><strong>${data.support.expand}</strong><span>유동층 ${data.support.floating}</span></article></div><div class="admin-message-market-v3"><span>핵심층 결집</span><b style="left:${data.support.core}%;top:${100-data.support.expand}%">김민석</b><span>대중 확장</span></div></section><section class="admin-pi-report-block admin-derived-chapter-v3">${adminHead('30-DAY CONSULTING ACTION','30일 실행계획','7일·14일·30일 우선순위')}<div class="admin-strategy-roadmap-v3 compact">${strategy}</div><div class="admin-action-kpi-v3"><span><b>7일</b>민생 성과 증거 확보</span><span><b>14일</b>세대별 메시지 분리</span><span><b>30일</b>검색·뉴스·지지 재측정</span></div></section><section class="admin-pi-report-block">${adminHead('JCS STRATEGIC CONSULTING','정치 전략 컨설팅','실행 가능한 메시지·채널·대응 순서')}<p class="admin-visual-reading-v3">${esc(data.conclusion)}</p></section><section class="admin-pi-report-block">${adminHead('HISTORY INTELLIGENCE','관측 이력 인텔리전스',`${data.snapshot} 스냅샷`)}<div class="admin-history-timeline-v3"><svg viewBox="0 0 580 125" role="img" aria-label="김민석 관측 이력"><line x1="20" y1="110" x2="560" y2="110"></line><polyline points="${historyPoints}"></polyline></svg><div><span>관측 ${data.trend.length}단계</span><span>최근 변화 +${data.trend.at(-1)-data.trend[0]}</span><span>근거 ${data.sources.length}범주</span></div></div></section></div></div></details>`;
}

function adminPublishedIntelligence(name,data){
  const index=['인구구조','지지구조','회복탄력','미디어','이슈','위험·기회','근거','전략'].map((label,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b>${label}</span>`).join('');
  const gate=adminGate({name,description:'허용 원자료와 JCS 해석을 분리한 정치 인텔리전스 리포트 (JCS 해석)',status:'LIVE',statusMeta:data.snapshot});
  const executive=adminExecutive({classification:'PUBLISHED INTELLIGENCE',title:data.signal.label,body:data.diagnosis.body,evidenceValue:String(data.sources.length),evidenceNote:'허용 원자료 범주',kpis:[{label:'NOW 지수',value:String(data.signal.index),note:`전체 ${data.rank.overall}위`},{label:'검색 신호',value:String(data.mediaScores.social),note:'PC·모바일 결합'},{label:'뉴스 도달',value:String(data.mediaScores.reach),note:`기사 ${data.news.length}건`},{label:'코호트',value:String(data.cohorts.length*2),note:'연령×성별 JCS 지수'}],pulseTitle:data.diagnosis.title,pulseValue:String(data.signal.index),index});
  const cohorts=adminCohortRows(data);
  const supportItems=[['핵심 지지층',data.support.core,'정당·공식 경력 기반'],['확장 지지층',data.support.expand,'대중 확장 가능성'],['유동층',data.support.floating,'관심 이동 가능성'],['이탈 위험',data.support.risk,'신호 변동 위험']].map(([label,value,note])=>({label,value,note}));
  const quality=[['충성도',data.support.loyalty],['행동성',data.support.action],['안정성',data.support.stability],['확장성',data.support.scalability]].map(([label,score])=>({label,score}));
  const waterfall=data.support.waterfall.map(([label,value],i)=>`<article><span>0${i+1}</span><b>${esc(label)}</b><div><i style="width:${clamp(value)}%"></i></div><strong>${value}</strong></article>`).join('');
  const recoveryPoints=data.resilience.curve.map((value,i)=>`${20+i*112},${118-clamp(value)}`).join(' '),recoveryArea=`20,118 ${recoveryPoints} ${20+(data.resilience.curve.length-1)*112},118`;
  const propagation=[['언론 도달',data.mediaScores.reach],['검색 확산',data.mediaScores.social],['자발 전파',data.mediaScores.organic],['지속 노출',data.mediaScores.persistence]].map(([label,value],i)=>`<article style="--flow:${value}%"><span>0${i+1}</span><b>${label}</b><strong>${value}</strong><i></i></article>`).join('');
  const issues=data.issues.map((item,i)=>`<article style="--issue-x:${item.impact}%;--issue-y:${100-item.persistence}%;--issue-size:${30+i*4}px"><i></i><div><b>${esc(item.title)}</b><span>${esc(item.kind)} · 영향 ${item.impact} · 지속 ${item.persistence}</span></div></article>`).join('');
  const competitors=data.competitors.map((item,i)=>`<article><span>${i+1}</span><b>${esc(item.name)}</b><div><i style="width:${item.score}%"></i></div><strong>${item.score}</strong><small>${esc(item.note)}</small></article>`).join('');
  const strategies=data.strategies.map((item,i)=>`<article><span>${i<2?'7일':i<5?'14일':'30일'}</span><div><small>PRIORITY ${String(i+1).padStart(2,'0')}</small><b>${esc(item.title)}</b><p>${esc(item.body)}</p></div></article>`).join('');
  const search=data.raw?.searchAds?.volume||null,pc=search?.pc??search?.pcRange?.max??0,mobile=search?.mobile??search?.mobileRange?.max??0,total=Number(pc||0)+Number(mobile||0),pcRate=total?Math.round(Number(pc||0)/total*100):0;
  const searchChapter=search?`<section class="admin-pi-report-block admin-derived-chapter-v3">${adminHead('DIGITAL DEMAND INTELLIGENCE','디지털 검색 수요','네이버 검색광고 PC·모바일 원본')}<div class="admin-opinion-conversion-v3"><article><b>PC 검색량</b><div><i style="width:${pcRate}%"></i></div><strong>${Number(pc).toLocaleString('ko-KR')}</strong></article><article><b>모바일 검색량</b><div><i style="width:${100-pcRate}%"></i></div><strong>${Number(mobile).toLocaleString('ko-KR')}</strong></article><article><b>모바일 비중</b><div><i style="width:${100-pcRate}%"></i></div><strong>${100-pcRate}%</strong></article></div></section>`:searchPendingChapters();
  const gap=data.core[0].score-data.transition[2].score,newsSources=new Set(data.news.map(item=>item.source)).size;
  return `<details class="admin-intelligence-report-shell jcs-private-intelligence-v3" data-design-system="jcs-private-intelligence-v3">${gate}<div class="admin-intelligence-report-body">${executive}<div class="admin-political-intelligence admin-pi-report-main"><section class="admin-pi-report-block">${adminHead('AGE × GENDER MATRIX','연령·성별 관심 구조','검색 기기·정당 맥락·공식 인구 JCS 지수')}<div class="admin-cohort-heatmap-v3"><header><span>연령</span><b>남성</b><b>여성</b></header>${cohorts}</div></section><section class="admin-pi-report-block">${adminHead('CORE SUPPORT DYNAMICS','핵심 지지 구조','허용 원자료 교차 해석')}${adminBarRows(supportItems)}<div class="admin-support-waterfall-v3">${adminHead('SUPPORT WATERFALL','지지 이동 폭포','관심에서 유지까지')}${waterfall}</div><div class="admin-support-quality-v3">${adminHead('SUPPORT QUALITY','지지 품질','충성·행동·안정·확장')}${radarVisual(quality,'admin-support-radar-v3',`${name} 지지 품질 레이더 차트`)}<div>${quality.map(item=>`<span><b>${item.label}</b><strong>${item.score}</strong></span>`).join('')}</div></div></section><section class="admin-pi-report-block">${adminHead('POLITICAL RESILIENCE','정치적 회복탄력성','공식 경력·관심 지속성')}<div class="admin-resilience-area-v3"><svg viewBox="0 0 600 130" role="img" aria-label="${esc(name)} 정치적 회복탄력성"><line x1="20" y1="40" x2="580" y2="40"></line><line x1="20" y1="80" x2="580" y2="80"></line><polygon points="${recoveryArea}"></polygon><polyline points="${recoveryPoints}"></polyline></svg><aside><span>RESILIENCE INDEX</span><strong>${data.resilience.index}</strong><dl><div><dt>충격 저항</dt><dd>${data.resilience.resistance}</dd></div><div><dt>회복 속도</dt><dd>${data.resilience.speed}</dd></div><div><dt>회복 안정성</dt><dd>${data.resilience.stability}</dd></div></dl></aside></div></section><section class="admin-pi-report-block">${adminHead('MEDIA PROPAGATION','미디어 전파 구조','Google 뉴스·네이버 검색광고')}<div class="admin-propagation-flow-v3">${propagation}</div><p class="admin-visual-reading-v3">언론 도달 ${data.mediaScores.reach}, 검색 확산 ${data.mediaScores.social}, 자발 전파 ${data.mediaScores.organic}의 차이가 채널 전환 우선순위를 결정한다.</p></section><section class="admin-pi-report-block">${adminHead('ISSUE IMPACT MAP','이슈 영향 지도','최근 보도 주제 분류')}<div class="admin-issue-quadrant-v3"><span class="x-axis">영향도 →</span><span class="y-axis">지속성 ↑</span>${issues}</div></section><section class="admin-pi-report-block">${adminHead('RISK & OPPORTUNITY','위험·기회 신호','근거 기반 실행 우선순위')}<div class="admin-risk-matrix-v3"><section><header><b>RISK SIGNALS</b><span>위험</span></header>${data.risks.map((text,i)=>`<article><strong>R${i+1}</strong><p>${esc(text)}</p></article>`).join('')}</section><section><header><b>OPPORTUNITY SIGNALS</b><span>기회</span></header>${data.opportunities.map((text,i)=>`<article><strong>O${i+1}</strong><p>${esc(text)}</p></article>`).join('')}</section></div><div class="admin-gap-dumbbell-v3"><header><b>ATTENTION → SUPPORT GAP</b><span>${gap}p 격차</span></header><div><i style="left:${data.transition[2].score}%"></i><em style="left:${data.core[0].score}%"></em><span></span></div><footer><b>지지 전환 ${data.transition[2].score}</b><b>관심 ${data.core[0].score}</b></footer></div><div class="admin-competitor-flow-v3">${adminHead('COMPETITOR FLOW','경쟁자 흐름','동일 지역·정당·분야 맥락')}${competitors}</div></section>${searchChapter}<section class="admin-pi-report-block">${adminHead('EVIDENCE BASE','분석 근거','허용 범주 원자료')}${sourceLedger(data.sources)}</section><section class="admin-pi-report-block admin-derived-chapter-v3">${adminHead('NEWS NARRATIVE INTELLIGENCE','뉴스 서사 인텔리전스','Google 뉴스 프레임 분류')}<div class="admin-news-narrative-v3"><article><small>수집 기사</small><strong>${data.news.length}</strong><span>건</span></article><article><small>고유 매체</small><strong>${newsSources}</strong><span>개</span></article><div>${data.issues.map(item=>`<span style="--frame:${item.impact}%"><b>${esc(item.title)}</b><i></i><strong>${item.impact}</strong></span>`).join('')}</div></div></section><section class="admin-pi-report-block">${adminHead('JCS STRATEGIC SOLUTION','JCS 전략 솔루션','7일·14일·30일 실행순서')}<div class="admin-strategy-roadmap-v3">${strategies}</div><div class="admin-pi-conclusion"><div><span>STRATEGIC CONCLUSION</span><small>최종 전략 제안</small></div><strong>${esc(data.conclusion)}</strong></div></section>${strategicConsulting()}</div></div></details>`;
}

function newsShell(){return `<section class="content-card"><div class="section-title"><div><span class="eyebrow">RECENT NEWS</span><h2>최근 뉴스</h2></div><span>뉴스 출처 미연결</span></div><div class="person-live-news-list"><div class="person-news-empty">검증할 뉴스 출처와 수집 기준을 협의한 뒤 표시합니다.</div></div></section>`;}
function relatedShell(){return `<section class="content-card"><div class="section-title"><div><span class="eyebrow">RELATED POLITICIANS</span><h2>같이 보면 좋은 정치인</h2></div><span>추천 기준 미연결</span></div><div class="person-related-grid pending-related-grid">${Array.from({length:4},()=>`<div class="pending-related-card"><span class="related-person-avatar"></span><span><b>—</b><small>데이터 준비 중</small></span></div>`).join('')}</div></section>`;}

function pilotNews(data){const rows=(data.news||[]).slice(0,10),first=rows.slice(0,5),more=rows.slice(5),row=(item,i)=>`<a href="${esc(item.url||'#')}" target="_blank" rel="noopener"><strong>${String(i+1).padStart(2,'0')}</strong><span><b>${esc(item.title)}</b><small>${esc(item.source)} · ${esc(item.date)} · ${esc(item.agendaTag||'정치 현안')} · 진단 ${(item.diagnosisRefs||[]).join('·')}</small></span><em>↗</em></a>`;return `<section class="content-card"><div class="section-title"><div><span class="eyebrow">RECENT NEWS</span><h2>대표 뉴스 헤드라인</h2></div><span>중복 정규화 · 매체 다변화 · 최대 10건</span></div><div class="person-live-news-list">${first.map(row).join('')}${more.length?`<details class="jcs-news-more"><summary>대표 뉴스 ${more.length}건 더보기</summary>${more.map((item,index)=>row(item,index+5)).join('')}</details>`:''}</div></section>`;}
function pilotRelated(data){return `<section class="content-card"><div class="section-title"><div><span class="eyebrow">RELATED POLITICIANS</span><h2>같이 보면 좋은 정치인</h2></div><span>직접 경선·정당·지역 맥락</span></div><div class="person-related-grid">${data.related.map(item=>`<button type="button" class="pending-related-card" data-layout-route="/person/${esc(item.id)}">${photoMarkup(item,'related-person-avatar',72)}<span><b>${esc(item.name)}</b><small>${esc(item.meta||[item.party,item.jurisdiction,item.office].filter(Boolean).join(' · '))}</small></span></button>`).join('')}</div></section>`;}

function strategicConsulting(){
  const services=[
    ['POLITICAL BRAND','정치인 이미지·브랜드 전략','정치적 포지션과 대중 인식을 하나의 브랜드 언어로 정렬'],
    ['DEMOGRAPHIC TARGET','세대·성별 타깃 전략','AGE × GENDER 흐름을 기준으로 우선 타깃과 메시지 분리'],
    ['LOCAL MESSAGE','지역별 메시지 전략','지역 이슈와 생활권 반응 차이를 반영한 메시지 설계'],
    ['CORE SUPPORT','핵심 지지층 관리','강성·적극·약지지층 이동의 이탈과 확장 신호 관리'],
    ['COMPETITOR RESPONSE','경쟁자 대응 전략','경쟁구도와 이슈 격차 데이터를 기반으로 대응 우선순위 설계'],
    ['ISSUE & CRISIS','이슈·위기 대응','이슈 발생 시점에 확산 속도·지속성·회복력에 맞춘 대응'],
    ['MEDIA PROPAGATION','언론·온라인 확산 전략','뉴스·SNS·커뮤니티 확산 흐름을 전환 가능한 콘텐츠로 연결'],
    ['CAMPAIGN DATA','선거·캠페인 데이터 전략','축적된 HISTORY와 시장 신호로 캠페인 실행 판단을 지원']
  ];
  return `<section class="person-strategic-consulting"><header><span>JCS STRATEGIC CONSULTING</span><h2>분석 다음은 실행입니다.</h2><p>정참시는 데이터를 보여주는 데서 끝나지 않습니다. 필요한 순간, 데이터가 가리키는 방향을 실제 정치 전략과 실행 언어로 바꿉니다.</p></header><div class="person-consulting-grid">${services.map((item,index)=>`<article><strong>${String(index+1).padStart(2,'0')}</strong><div><small>${item[0]}</small><b>${item[1]}</b><p>${item[2]}</p></div></article>`).join('')}</div><footer><div><span>DATA TELLS YOU WHERE.<br>STRATEGY TELLS YOU HOW.</span><b>목적지는 여러분이 정합니다.<br>가장 정확한 경로는 정참시가 찾겠습니다.</b></div><button type="button" data-layout-route="/partners">정참시와 함께하기 <em>→</em></button></footer></section>`;
}

const diagnosticText=value=>{
  if(value===null||value===undefined||value==='')return '';
  if(typeof value==='string'||typeof value==='number')return esc(value);
  if(Array.isArray(value))return value.map(item=>`<span>${diagnosticText(item)}</span>`).join('');
  if(typeof value==='object'){
    const label=value.label||value.title||value.age||value.type||'',metric=value.value??value.score??value.overall??value.category;
    if(label||metric!==undefined)return `<span>${label?`<b>${esc(label)}</b>`:''}${metric!==undefined&&metric!==null?`<strong>${esc(metric)}</strong>`:''}${value.body?`<em>${esc(value.body)}</em>`:''}${value.detail?`<em>${esc(value.detail)}</em>`:''}${value.note?`<em>${esc(value.note)}</em>`:''}${value.male!==undefined||value.female!==undefined?`<em>남성 ${value.male??'—'} · 여성 ${value.female??'—'}</em>`:''}</span>`;
    return Object.entries(value).map(([key,item])=>`<span><b>${esc(key)}</b>${diagnosticText(item)}</span>`).join('');
  }
  return '';
};

function diagnosticTrend(value){
  const points=(Array.isArray(value?.periods)?value.periods.map(row=>row.value):Array.isArray(value?.values)?value.values:[]).filter(hasMetric);
  const bars=points.length?`<div class="jcs-diagnostic-spark" aria-label="관측값 흐름">${points.map(point=>`<i style="--point:${clamp(point)}%"></i>`).join('')}</div>`:'';
  return `${bars}<p>${esc(value?.direction||'유지')}</p>${Array.isArray(value?.periods)?`<small>${value.periods.map(row=>`${esc(row.label)} ${esc(row.value)}`).join(' · ')}</small>`:''}`;
}

function diagnosticSources(value){
  const rows=Array.isArray(value)?value:[];
  return rows.length?rows.map(row=>`<span><b>${esc(row.type||'출처')}</b>${row.title?`<em>${esc(row.title)}</em>`:''}${row.detail?`<small>${esc(row.detail)}</small>`:''}</span>`).join(''):'<span>데이터 출처 연결 전</span>';
}

const diagnosticBlock=(label,content,className='')=>`<div class="jcs-diagnostic-field ${className}"><b>${esc(label)}</b><div>${content}</div></div>`;

const DIAGNOSIS_VISUALS={
  '01':'positioning','02':'cohort-heatmap','03':'local-fit','04':'support-stack','05':'competitor-matrix',
  '06':'risk-matrix','07':'narrative-timeline','08':'campaign-matrix','09':'policy-heatmap','10':'growth-ladder'
};
function diagnosisVisual(topic,isDiagnosis=true){const visual=topic.visualization||{},bars=Array.isArray(visual.bars)?visual.bars:Array.isArray(visual.rows)?visual.rows:Array.isArray(visual.segments)?visual.segments:Array.isArray(visual.points)?visual.points:[],kind=DIAGNOSIS_VISUALS[topic.id]||'index',diagnosisAttr=isDiagnosis?` data-diagnosis-visual="${kind}"`:'';return `<div class="jcs-v2-visual jcs-diagnosis-visual-${kind}"${diagnosisAttr} data-visual-type="${esc(visual.type||'index')}">${bars.slice(0,6).map((row,index)=>{const label=row.label||row.name||row.age||`지표 ${index+1}`,hasCohortValues=topic.id==='02'&&(hasMetric(row.left)||hasMetric(row.right));if(hasCohortValues){const left=hasMetric(row.left)?row.left:'—',right=hasMetric(row.right)?row.right:'—',values=[row.left,row.right].filter(hasMetric).map(Number),number=values.length?values.reduce((sum,value)=>sum+value,0)/values.length:0;return `<span class="is-cohort"><b>${esc(label)}</b><i><em style="width:${clamp(number)}%"></em></i><strong>남성 ${esc(left)} · 여성 ${esc(right)}</strong></span>`;}const number=row.value??row.score??row.male??topic.score;return `<span><b>${esc(label)}</b><i><em style="width:${clamp(number)}%"></em></i><strong>${esc(number)}</strong></span>`;}).join('')||`<div class="jcs-v2-score"><strong>${esc(topic.score)}</strong><span>JCS 상대지수</span></div>`}</div>`;}

function renderPublicDiagnostic(topic){const primary=topic.id==='01';return `<article class="jcs-diagnostic-topic jcs-diagnostic-public-topic" data-diagnostic-topic="${topic.id}"><header><span>${topic.id}</span><h3>${esc(topic.title)}</h3><em>${esc(topic.attentionQuality||topic.trend?.direction||'유지')}</em></header><strong>${esc(topic.headline)}</strong>${primary?`<div class="jcs-diagnostic-event"><b>핵심 사건</b><p>${esc(topic.coreEvent)}</p></div>`:''}<div class="jcs-diagnostic-meaning"><b>정치적 의미</b><p>${esc(topic.politicalMeaning)}</p></div>${diagnosisVisual(topic)}<div class="jcs-diagnostic-public-visual">${primary?diagnosticTrend(topic.trend):''}<b>${esc(topic.score)} · ${esc(topic.trend?.direction||'유지')}</b></div></article>`;}

function renderMemberDiagnostic(topic){const primary=topic.id==='01';return `<article class="jcs-diagnostic-topic jcs-diagnostic-member-topic" data-diagnostic-topic="${topic.id}"><header><span>${topic.id}</span><div><small>JCS MEMBER ANALYSIS</small><h3>${esc(topic.title)}</h3></div><em>${esc(topic.percentile)}</em></header>${diagnosisVisual(topic)}<div class="jcs-diagnostic-member-grid">${diagnosticBlock('현재 평가',`<p>${esc(topic.currentPosition)}</p>`,'is-summary')}${primary?diagnosticBlock('핵심 사건',`<p>${esc(topic.coreEvent)}</p>`,'is-event'):''}${diagnosticBlock('정치적 의미',`<p>${esc(topic.politicalMeaning)}</p>`,'is-meaning')}${primary?diagnosticBlock('변화 원인',`<p>${esc(topic.changeReason)}</p>`):''}${primary?diagnosticBlock('과거와 현재',`<p>${esc(topic.pastPresentConnection)}</p>`):''}${diagnosticBlock('핵심 수치',`<strong>${esc(topic.score)}</strong><span>${esc(topic.percentile)}</span>`)}${primary?diagnosticBlock('최근 변화',diagnosticTrend(topic.trend)):''}${diagnosticBlock('비교 기준',diagnosticText(topic.benchmark))}${diagnosticBlock('정참시 해석',diagnosticText(topic.interpretation),'is-interpretation')}${topic.id==='06'?diagnosticBlock('서브데이터',diagnosticText(topic.supportingData),'is-supporting'):''}${diagnosticBlock('데이터 기준일 및 출처',`<p>${esc(topic.updatedAt)}</p><span>${(topic.sourceTypes||[]).map(esc).join(' · ')}</span>`,'is-source')}</div></article>`;}

const dxNum=value=>value===null||value===undefined||value===''?null:Number.isFinite(Number(value))?Number(value):null;
const dxValue=(value,suffix='')=>dxNum(value)===null?'데이터 부족':`${Number(value).toLocaleString('ko-KR')}${suffix}`;
const dxCompact=value=>{const number=dxNum(value);if(number===null)return '데이터 부족';if(Math.abs(number)>=1000000)return `${Math.round(number/100000)/10}M`;if(Math.abs(number)>=1000)return `${Math.round(number/1000)}K`;return number.toLocaleString('ko-KR');};
const dxStatus=value=>`<div class="jcs-dx-status">${esc(value||'데이터 수집 중')}</div>`;
const dxSignedAxis=(label,value)=>{const number=Math.max(-50,Math.min(50,dxNum(value)||0)),position=number+50;return `<div class="jcs-dx-brand-axis"><b>${esc(label)}</b><div><i style="left:${position}%"></i><span></span></div><strong>${number>0?'+':''}${number}</strong></div>`;};
const dxStat=(label,value,detail='')=>`<article class="jcs-dx-stat"><small>${esc(label)}</small><strong>${esc(value)}</strong>${detail?`<span>${esc(detail)}</span>`:''}</article>`;
function renderDxBrand(data){const risks=Array.isArray(data.pastRisks)?data.pastRisks:[],indicators=data.indicators||[],score=index=>Math.max(0,Math.min(100,Number(indicators[index]?.value||0)+50)),segments=index=>Array.from({length:6},(_,slot)=>`<i class="${slot<Math.round(score(index)/17)?'is-on':''}"></i>`).join(''),searchMax=Math.max(1,Number(data.search?.pc)||0,Number(data.search?.mobile)||0),searchDevice=(label,value)=>`<div class="jcs-dx-search-device"><strong aria-label="정확한 검색량 ${dxValue(value)}" title="${dxValue(value)}">${dxCompact(value)}</strong><i style="--dx-search-height:${Math.max(14,Math.round((Number(value)||0)/searchMax*86))}px"></i><span>${label}</span></div>`;return `<div class="jcs-dx-stack"><section class="jcs-dx-signal"><small>NOW SIGNAL</small><strong>${esc(data.nowSignal||'데이터 수집 중')}</strong></section><section class="jcs-dx-panel jcs-dx-brand-panel"><h4>BRAND INDICATORS</h4><div class="jcs-dx-brand-tools"><article class="jcs-dx-brand-tool is-clarity"><h5>브랜드 선명도</h5><div class="jcs-dx-brand-ring" style="--dx-score:${score(0)}"><strong>${score(0)}</strong></div></article><article class="jcs-dx-brand-tool is-policy"><h5>정책 연결도</h5><strong>${score(1)}</strong><div class="jcs-dx-brand-segments">${segments(1)}</div></article><article class="jcs-dx-brand-tool is-consistency"><h5>이미지 일관성</h5><svg viewBox="0 0 180 96" role="img" aria-label="이미지 일관성 ${score(2)}"><path d="M8 70 L40 42 L72 65 L104 30 L138 54 L172 ${82-Math.round(score(2)/2)}" fill="none"/><path class="is-area" d="M8 70 L40 42 L72 65 L104 30 L138 54 L172 ${82-Math.round(score(2)/2)} L172 88 L8 88 Z"/></svg><strong>${score(2)}</strong></article><article class="jcs-dx-brand-tool is-difference"><h5>경쟁자 차별성</h5><div class="jcs-dx-difference-row"><span>본인</span><i><em style="width:${score(3)}%"></em></i><b>${Number(indicators[3]?.value||0)>0?'+':''}${Number(indicators[3]?.value||0)}</b></div><div class="jcs-dx-difference-row is-average"><span>평균</span><i><em style="width:50%"></em></i><b>0</b></div></article><article class="jcs-dx-brand-tool is-expansion"><h5>확장성</h5><div class="jcs-dx-radar" style="--dx-score:${score(4)}"><i></i><i></i><i></i><i></i><i></i><strong>${score(4)}</strong></div></article><article class="jcs-dx-brand-tool is-search"><h5>서칭엔진 검색추이</h5><div class="jcs-dx-search-trend">${searchDevice('PC',data.search?.pc)}${searchDevice('MOBILE',data.search?.mobile)}</div></article></div></section><section class="jcs-dx-panel jcs-dx-brand-bottom"><div><h4>PAST RISK SIGNALS</h4>${risks.length?`<div class="jcs-dx-risk-tags">${risks.map(row=>`<a href="${esc(row.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(row.tag)}</b><span>↗</span></a>`).join('')}</div>`:dxStatus('관리자 등록 신호 없음')}</div><div><h4>BRAND TOTAL SIGN</h4><div class="jcs-dx-total-sign"><div class="is-risk"><i style="width:${Math.min(100,Number(data.totalSign?.risk||0)*2)}%"></i></div><b>중립</b><div class="is-opportunity"><i style="width:${Math.min(100,Number(data.totalSign?.opportunity||0)*2)}%"></i></div></div><div class="jcs-dx-axis-labels"><span>위험 −50</span><span>양방향 신호</span><span>기회 +50</span></div></div></section></div>`;}
function renderDxDemographic(data){const rows=data.cohorts||[],max=Math.max(1,...rows.map(row=>Number(row.total)||0)),rank=(title,items)=>`<div><b>${title} 기반 순위</b><span>${(items||[]).map(row=>esc(String(row.age).replace(' 이상','+'))).join(' → ')}</span></div>`;return `<section class="jcs-dx-panel jcs-dx-demographic-card"><h4>${esc(data.label||'JCS 연령·성별 지지구조 해석')}</h4><div class="jcs-dx-gender-legend"><span><i class="is-man"></i>남성</span><span><i class="is-woman"></i>여성</span></div><div class="jcs-dx-age-chart"><div class="jcs-dx-age-gridlines" aria-hidden="true"><i><span>25%</span></i><i><span>20%</span></i><i><span>15%</span></i><i><span>10%</span></i><i><span>5%</span></i></div><div class="jcs-dx-age-columns" aria-label="연령별 지지 기반 구성 합계 100퍼센트, 각 연령별 남녀 구성 합계 100퍼센트">${rows.map(row=>`<article class="jcs-dx-age-column"><div class="jcs-dx-age-bars" style="--jcs-height:${Math.max(58,Math.round((Number(row.total)||0)/max*190))}px"><span class="jcs-dx-man">${dxValue(row.male)}</span><span class="jcs-dx-woman">${dxValue(row.female)}</span></div><strong class="jcs-dx-age-total">${dxValue(row.total,'%')}</strong><span class="jcs-dx-age-label">${esc(String(row.age).replace(' 이상','+'))}</span></article>`).join('')}</div></div><div class="jcs-dx-rank-lines">${rank('남성',data.maleRank)}${rank('여성',data.femaleRank)}</div><p class="jcs-dx-demographic-insight">${esc(data.interpretation)}</p></section>`;}
function renderDxLocal(data){const issues=data.issues||[],population=data.population||[],messagePath=data.messagePath||[],ageMax=Math.max(1,...population.map(row=>Number(row.totalShare)||0)),issueMax=Math.max(1,...issues.map(row=>Number(row.count)||0));return `<div class="jcs-dx-local-layout"><section class="jcs-dx-panel"><h4>지역 유권자 구조 <span>${esc(data.populationBasis||'')}</span></h4><div class="jcs-dx-local-demography"><div class="jcs-dx-local-ages">${population.map(row=>`<article><div><i style="height:${Math.max(12,Math.round((Number(row.totalShare)||0)/ageMax*100))}%"></i></div><strong>${dxValue(row.totalShare,'%')}</strong><span>${esc(String(row.age).replace(' 이상','+'))}</span></article>`).join('')}</div><div class="jcs-dx-local-genders">${population.map(row=>`<article><b>${esc(String(row.age).replace(' 이상','+'))}</b><div><i class="is-man" style="width:${Number(row.maleShare)||0}%"></i><i class="is-woman" style="width:${Number(row.femaleShare)||0}%"></i></div><span>남 ${dxValue(row.maleShare,'%')}</span><span>여 ${dxValue(row.femaleShare,'%')}</span></article>`).join('')}</div></div></section><section class="jcs-dx-panel"><h4>지역 메시지 경로 <span>JCS 지역 진단</span></h4><div class="jcs-dx-local-path">${messagePath.map((row,index)=>`<article><span>${String(index+1).padStart(2,'0')}</span><div><b>${esc(row.label)}</b><i><em style="width:${Number(row.value)||0}%"></em></i></div><strong>${dxValue(row.value)}</strong></article>`).join('')}</div><p class="jcs-dx-local-judgment">${esc(data.localJudgment)}</p></section>${issues.length?`<section class="jcs-dx-panel jcs-dx-local-evidence"><h4>지역 의제 근거 <span>지역명·지역 행정 의제 확인 기사만 사용</span></h4><div class="jcs-dx-local-issues">${issues.map(row=>`<span><b>${esc(row.label)}</b><i><em style="width:${Math.round(Number(row.count||0)/issueMax*100)}%"></em></i><strong>${dxValue(row.count,'건')}</strong>${(row.evidence||[]).slice(0,2).map(item=>`<a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.title)} ↗</a>`).join('')}</span>`).join('')}</div></section>`:''}<section class="jcs-dx-panel jcs-dx-local-overlap"><h4>지역 민심·메시지 판정</h4><div class="jcs-dx-local-verdict">${messagePath.map(row=>`<span style="--dx-value:${Number(row.value)||0}%"><b>${esc(row.label)}</b><i></i><strong>${Number(row.value)>=62?'강함':Number(row.value)<42?'보강':'경합'}</strong></span>`).join('')}</div></section></div>`;}
function renderDxSupport(data){const byKey=new Map((data.composition||[]).map(row=>[row.key,row]));return `<section class="jcs-dx-panel jcs-dx-support"><h4>SUPPORT COMPOSITION</h4><div class="jcs-dx-support-visuals" aria-label="코어 ${dxValue(byKey.get('core')?.value,'%')}, 유동 ${dxValue(byKey.get('floating')?.value,'%')}, 이탈 ${dxValue(byKey.get('exit')?.value,'%')}">${[['core','코어'],['floating','유동'],['exit','이탈']].map(([key,label])=>`<article class="jcs-dx-support-item"><div class="jcs-dx-support-shape jcs-dx-${key}-shape"><strong>${dxValue(byKey.get(key)?.value,'%')}</strong></div><b>${label}</b></article>`).join('')}</div></section>`;}
function renderDxCompetitor(data){const rows=data.people||[],cell=(value,suffix='')=>dxNum(value)===null?'<span class="is-pending">미수집</span>':`<strong>${dxValue(value,suffix)}</strong>`,competition=row=>row.election&&row.election.voteRate!==null?`${dxValue(row.election.voteRate,'%')}${row.election.margin===null?'':` · ${Number(row.election.margin)>0?'+':''}${dxValue(row.election.margin,'%p')}`}`:`JCS ${dxValue(row.competition?.index)}`;return `<section class="jcs-dx-panel"><h4>경쟁 정치인 직접 비교</h4><div class="jcs-dx-competitor-grid" style="--dx-people:${Math.max(1,rows.length)}"><div class="jcs-dx-competitor-head"><b>비교 지표</b>${rows.map((row,index)=>`<article class="${index===0?'is-subject':''}"><i>${esc(String(row.name||'?').slice(0,1))}</i><strong>${esc(row.name)}</strong><span>${esc([row.party,row.region].filter(Boolean).join(' · '))}</span></article>`).join('')}</div><div class="jcs-dx-competitor-row"><b>전체·분야별 NOW</b>${rows.map(row=>`<div>${cell(row.overallRank,'위')}<span> / </span>${cell(row.categoryRank,'위')}</div>`).join('')}</div><div class="jcs-dx-competitor-row"><b>PC·모바일 검색량</b>${rows.map(row=>`<div>${cell(row.pc)}<span> / </span>${cell(row.mobile)}</div>`).join('')}</div><div class="jcs-dx-competitor-row"><b>24H · 7D · 30D 뉴스</b>${rows.map(row=>`<div class="jcs-dx-period-values">${row.newsPeriods?.length?row.newsPeriods.map(period=>`<span>${esc(period.label)} <strong>${dxValue(period.value,'건')}</strong></span>`).join(''):'<span class="is-pending">미수집</span>'}</div>`).join('')}</div><div class="jcs-dx-competitor-row"><b>긍정 · 중립 · 부정</b>${rows.map(row=>`<div class="jcs-dx-frame-values">${row.frames?`<span class="is-positive">${dxValue(row.frames.positive)}</span><span class="is-neutral">${dxValue(row.frames.neutral)}</span><span class="is-negative">${dxValue(row.frames.negative)}</span>`:'<span class="is-pending">미수집</span>'}</div>`).join('')}</div><div class="jcs-dx-competitor-row"><b>주요 의제 점유율</b>${rows.map(row=>`<div>${row.agendas?.length?row.agendas.map(item=>`<span>${esc(item.label)} ${dxValue(item.share,'%')}</span>`).join('<br>'):'<span class="is-pending">미수집</span>'}</div>`).join('')}</div><div class="jcs-dx-competitor-row"><b>최근 선거·현재 경쟁 신호</b>${rows.map(row=>`<div><strong>${competition(row)}</strong></div>`).join('')}</div></div></section>`;}
function renderDxRisk(data){const direction=Math.max(-50,Math.min(50,Number(data.direction)||0)),position=direction+50,p=data.persistence||{},days=p.daily||[],max=Math.max(1,Number(p.maxDaily)||0);return `<div class="jcs-dx-stack"><section class="jcs-dx-signal"><small>NOW SIGNAL</small><strong>${esc(data.nowSignal||'데이터 수집 중')}</strong></section><section class="jcs-dx-panel"><h4>이슈 방향 <span>부정 −50 · 중립 0 · 긍정 +50</span></h4><div class="jcs-dx-issue-axis"><i style="left:${position}%"></i></div><div class="jcs-dx-axis-labels"><span>부정 −50</span><span>중립 0</span><span>긍정 +50</span></div></section><div class="jcs-dx-split"><section class="jcs-dx-panel"><h4>이슈 확산 속도</h4><div class="jcs-dx-velocity">${(data.velocity||[]).map(row=>`<span><i style="height:${Math.min(100,Math.max(8,Number(row.value||0)*14))}%"></i><b>${esc(row.label)}</b><strong>${dxValue(row.value,'건')}</strong></span>`).join('')}</div></section><section class="jcs-dx-panel"><h4>이슈 지속력 <span>30일 실제 기사 발생일</span></h4><div class="jcs-dx-persistence"><div class="jcs-dx-day-strip jcs-dx-persistence-curve" aria-label="30일 이슈 기사 발생 분포">${days.map(row=>`<i class="jcs-dx-day" style="--jcs-level:${Math.ceil((Number(row.count)||0)/max*3)}" title="${esc(`${row.date} · ${row.count}건`)}"></i>`).join('')}</div><div class="jcs-dx-days"><span>D−30</span><span>D−21</span><span>D−14</span><span>D−7</span><span>오늘</span></div><div class="jcs-dx-stat-grid">${dxStat('최초',p.from||'관측 없음')}${dxStat('최근',p.to||'관측 없음')}${dxStat('지속',p.durationDays?dxValue(p.durationDays,'일'):'관측 없음')}${dxStat('재점화',dxValue(p.reignitionCount,'회'))}</div></div></section></div></div>`;}
function renderDxMedia(data){const all=data.allSources||[],top=all.slice(0,11),maxCount=Math.max(1,...top.map(row=>Number(row.count)||0)),tile=row=>`<span class="jcs-dx-media-tile ${data.majorOutletNames?.includes(row.name)?'is-major':''}" style="--dx-tile:${Math.max(1,Math.round((Number(row.count)||0)/maxCount*6))}"><b>${esc(row.name)}</b></span>`,sourceRow=(row,index)=>`<div class="jcs-dx-source-row"><em>${String(index+1).padStart(2,'0')}</em><b>${esc(row.name)}</b><i style="--jcs-share:${Number(row.share)||0}%"></i><strong>${dxValue(row.count,'건')}</strong><span>${dxValue(row.share,'%')}</span></div>`;return `<div class="jcs-dx-stack"><section class="jcs-dx-panel"><div class="jcs-dx-media-summary"><div><small>언론 노출 규모</small><strong>${dxValue(data.articleCount,'건')}</strong></div><div><small>매체 확산 범위</small><strong>${dxValue(data.sourceCount,'개')}</strong></div><div><small>5대 메이저</small><strong>${dxValue(data.majorShare,'%')}</strong></div><div><small>비메이저</small><strong>${dxValue(data.nonMajorShare,'%')}</strong></div></div></section><section class="jcs-dx-panel"><h4>매체 집중도 <span>보도량에 따라 면적 배분</span></h4><div class="jcs-dx-media-treemap">${top.map(tile).join('')}</div><details class="jcs-dx-more-sources"><summary><span>전체 ${all.length}개 매체</span><b>전체 목록 보기 ＋</b></summary><div class="jcs-dx-source-table jcs-dx-media-legend">${all.map(sourceRow).join('')}</div></details></section><div class="jcs-dx-grid-2"><section class="jcs-dx-panel"><h4>메시지 주도권</h4><div class="jcs-dx-ownership"><span style="flex:${Math.max(1,Number(data.ownership?.led)||0)}">본인 주도 ${dxValue(data.ownership?.led,'건')}</span><span style="flex:${Math.max(1,Number(data.ownership?.external)||0)}">외부 발생 ${dxValue(data.ownership?.external,'건')}</span></div></section><section class="jcs-dx-panel"><h4>의제별 언론 침투력</h4><div class="jcs-dx-agenda-heat">${(data.agendaPenetration||[]).map(row=>`<span style="--dx-strength:${Math.min(100,Number(row.outlets||0)*18+20)}%"><b>${esc(row.label)}</b><strong>${dxValue(row.outlets,'개 매체')}</strong></span>`).join('')}</div></section></div><section class="jcs-dx-panel jcs-dx-youtube-slot"><h4>유튜브 채널 영향력</h4><p>채널 API 연결 후 구독자·최근 1개월 평균 조회수를 표시합니다.</p><span>API 연결 대기</span></section></div>`;}
function renderDxCampaign(data){const icon={career:'◆',regional:'⌖',support:'◎',competition:'↗'};return `<div class="jcs-dx-stack"><section class="jcs-dx-panel"><h4>정치 기반 흐름</h4><div class="jcs-dx-foundations">${(data.foundations||[]).map(row=>`<article class="is-${esc(row.key)}"><span>${icon[row.key]||'•'}</span><b>${esc(row.label)}</b><strong>${dxValue(row.value)}</strong><i><em style="width:${Number(row.value)||0}%"></em></i></article>`).join('')}</div></section><section class="jcs-dx-panel"><h4>지역별 우세·경합·취약 구조 <span>JCS 해석</span></h4><div class="jcs-dx-region-status">${(data.regionalStructure||[]).map(row=>`<article class="is-${row.status==='강함'?'lead':row.status==='약함'?'weak':'close'}"><div><b>${esc(row.name)}</b><small>${esc(row.basis)}</small></div><strong>${esc(row.status)}</strong><i style="--dx-value:${Number(row.value)||0}%"></i></article>`).join('')}</div></section></div>`;}
function renderDxAction(data){const max=Math.max(1,...(data.composition||[]).map(row=>Number(row.value)||0));return `<div class="jcs-dx-stack"><section class="jcs-dx-panel"><h4>정치 활동 구성</h4><div class="jcs-dx-action-composition">${(data.composition||[]).map(row=>`<div><span>${esc(row.label)}</span><i><em style="width:${Math.round((Number(row.value)||0)/max*100)}%"></em></i><b>${dxValue(row.value,'%')}</b></div>`).join('')}</div></section><section class="jcs-dx-panel"><h4>이슈 선점·합류</h4><div class="jcs-dx-action-metrics">${dxStat('직접 선점',dxValue(data.initiative?.firstMover,'건'))}${dxStat('이슈 합류',dxValue(data.initiative?.joined,'건'))}${dxStat('관측 활동',dxValue(data.activityCount,'건'))}${dxStat('관련 보도',dxValue(data.conversion?.total,'건'))}</div></section><section class="jcs-dx-panel"><h4>활동 → 미디어 전환</h4><div class="jcs-dx-conversion"><div><strong>${dxValue(data.activityCount)}</strong><span>관측 행보</span></div><i></i><div><strong>${dxValue(data.conversion?.led)}</strong><span>본인 주도 기사</span></div><i></i><div><strong>${dxValue(data.conversion?.external)}</strong><span>외부 발생 기사</span></div></div><div class="jcs-dx-action-list">${(data.activities||[]).slice(0,5).map(row=>`<a href="${esc(row.evidenceUrl)}" target="_blank" rel="noopener noreferrer"><span>${esc(row.category)}</span><b>${esc(row.title)}</b><em>↗</em></a>`).join('')}</div></section></div>`;}
function renderDxSummary(data){return `<div class="jcs-dx-summary"><section class="jcs-dx-total-score"><small>JCS TOTAL</small><strong>${dxValue(data.totalScore)}</strong><span>종합점수</span></section><div class="jcs-dx-summary-grid">${(data.items||[]).map(row=>`<article data-summary-source="${esc(row.sourceId)}"><header><b>${esc(row.label)}</b><span>DIAGNOSIS ${esc(row.sourceId)}</span></header><strong>${dxValue(row.value)}</strong><p>${esc(row.detail)}</p><i><em style="width:${Number(row.value)||0}%"></em></i></article>`).join('')}</div></div>`;}
export function renderDiagnosisDisplay(topic){const data=topic?.display||{};const body=({brand:renderDxBrand,demographic:renderDxDemographic,local:renderDxLocal,support:renderDxSupport,competitor:renderDxCompetitor,risk:renderDxRisk,media:renderDxMedia,campaign:renderDxCampaign,action:renderDxAction,summary:renderDxSummary}[data.kind]||(()=>dxStatus('표시 가능한 진단 데이터 부족')))(data);return `<div class="jcs-diagnosis-display" data-diagnosis-display="${esc(data.kind||'empty')}">${body}</div>`;}
const diagnosisDisplay=renderDiagnosisDisplay;
function renderAdminDiagnostic(topic){return `<article class="jcs-diagnostic-topic jcs-diagnostic-admin-topic jcs-dx-module" data-diagnostic-topic="${topic.id}" data-diagnosis-layout="${topic.id}"><header><span>${topic.id}</span><div><small>DIAGNOSIS ${topic.id}</small><h3>${esc(topic.title)}</h3></div><em>${esc(topic.updatedAt||'')}</em></header><div class="jcs-dx-body">${diagnosisDisplay(topic)}</div></article>`;}

function renderPrescription(item){return `<article class="jcs-prescription-card" data-prescription-topic="${item.id}"><header><span>${item.id}</span><div><small>STRATEGY PRESCRIPTION</small><h3>${esc(item.title)}</h3></div><em>${esc(item.priority)}</em></header>${diagnosisVisual({...item,score:item.visualization?.axes?.impact||70})}<div class="jcs-prescription-grid">${diagnosticBlock('진단 근거',diagnosticText(Array.isArray(item.sourceFindings)&&item.sourceFindings.length?item.sourceFindings:item.diagnosisBasis),'is-basis')}${diagnosticBlock('목표',`<p>${esc(item.objective)}</p>`)}${diagnosticBlock('정참시 전략 판단',`<p>${esc(item.strategicJudgment)}</p>`,'is-judgment')}${diagnosticBlock('실행 처방',diagnosticText(item.actions),'is-action')}${diagnosticBlock('타깃·메시지',`<p>${esc(item.target)} · ${esc(item.messageDirection)}</p>`)}${diagnosticBlock('채널·시점',`<p>${(item.channels||[]).map(esc).join(' · ')} · ${esc(item.timing)}</p>`)}${diagnosticBlock('예상 변화 및 추적 지표',`<p>${esc(item.expectedImpact)}</p>${diagnosticText(item.monitoringIndicators)}`,'is-monitoring')}</div></article>`;}
function diagnosisSummary(value){return `<section class="jcs-v2-summary"><article><b>가장 강한 정치 자산</b><p>${esc(value?.strongestAsset)}</p></article><article><b>구조적 취약점</b><p>${esc(value?.structuralWeakness)}</p></article><article><b>향후 성장 변수</b><p>${esc(value?.growthVariable)}</p></article></section>`;}
function priorityBoard(value,prescriptions){const byId=new Map((prescriptions||[]).map(row=>[row.id,row]));return `<section class="jcs-priority-board"><header><span>EXECUTION PRIORITY</span><h2>실행 우선순위</h2></header><div>${[['즉시 실행','immediate'],['30일 이내 실행','days30'],['90일 이내 실행','days90'],['중장기 관리','longTerm']].map(([label,key])=>`<article><b>${label}</b>${(value?.[key]||[]).map(id=>`<span>${esc(id)} · ${esc(byId.get(id)?.title)}</span>`).join('')}</article>`).join('')}</div></section>`;}
function politicianTypeCard(value){if(!value)return '';const evidence=(value.typeEvidence||[]).slice(0,2).map(item=>typeof item==='object'?(item.statement||item.label||item.value||''):item).filter(Boolean);return `<section class="jcs-politician-type" data-politician-type="${esc(value.primaryType)}"><div><span>POLITICAL TYPE</span><strong>${esc(value.primaryType)}</strong><small>${(value.secondaryTypes||[]).map(esc).join(' · ')}</small></div><div><span>CURRENT PHASE</span><strong>${esc(value.currentPhase)}</strong><small>${evidence.map(esc).join(' · ')}</small></div></section>`;}
function diagnosisWithReportContext(topic,report){if(topic?.id!=='05'||!topic.display?.people?.length)return topic;const people=topic.display.people.map((person,index)=>index?person:{...person,overallRank:report?.rank?.overall??null,categoryRank:report?.rank?.category??null});return {...topic,display:{...topic.display,people}};}

function roleDiagnostics(data,item={}){const topics=Array.isArray(data?.diagnoses)?data.diagnoses:[],role=data?.accessTier||'public',newsGuide='<small class="jcs-representative-news-guide">대표 뉴스는 핵심 이슈 주제에서 벗어난 관련 기사 집계를 의미합니다.</small>';if(!topics.length)return '';
  if(role==='admin'){const prescriptions=Array.isArray(data.prescriptions)?data.prescriptions:[],adminTopics=topics.map(topic=>diagnosisWithReportContext(topic,data));return `<section class="jcs-diagnostics-report jcs-diagnostics-admin"><header class="jcs-diagnostics-heading"><span>JCS ADMIN POLITICAL INTELLIGENCE</span><h2>${esc(item.name)} 정치 인텔리전스 진단서</h2><p>${esc(data.stInterpretation)}</p>${newsGuide}</header>${politicianTypeCard(data.politicianType)}<nav class="jcs-report-index"><b>REPORT INDEX</b><span>PART 01 · 정치 진단 10개</span><span>PART 02 · 전략 처방 10개</span><span>PART 03 · 실행 우선순위</span></nav><div class="jcs-diagnosis-part"><header><span>PART 01</span><h2>정치 진단</h2><p>수집된 근거를 9개 진단과 JCS 종합해석으로 정리합니다.</p></header>${adminTopics.map(renderAdminDiagnostic).join('')}</div><section class="jcs-report-transition"><span>FROM DIAGNOSIS TO PRESCRIPTION</span><h2>진단이 처방의 근거가 됩니다.</h2><p>아래 처방은 위 10개 진단 결과를 연결해 실행 순서로 전환한 관리자 전용 전략입니다.</p></section><div class="jcs-prescription-part"><header><span>PART 02</span><h2>전략 처방</h2><p>진단과 분리하여 목표·메시지·타깃·채널·시점·추적 지표를 제시합니다.</p></header>${prescriptions.map(renderPrescription).join('')}</div>${priorityBoard(data.prescriptionPriorities,prescriptions)}</section>`;}
  if(role==='member')return `<section class="jcs-diagnostics-report jcs-diagnostics-member"><header class="jcs-diagnostics-heading"><span>JCS MEMBER POLITICAL ANALYSIS</span><h2>정참시 정치인 상세 분석</h2><p>현재 상태와 변화, 비교 결과와 정참시 해석을 확인합니다.</p>${newsGuide}</header>${topics.map(renderMemberDiagnostic).join('')}</section>`;
  return `<section class="jcs-diagnostics-report jcs-diagnostics-public"><header class="jcs-diagnostics-heading"><span>JCS OPEN POLITICAL SNAPSHOT</span><h2>정참시 정치인 현재 진단</h2><p>현재 공개 데이터에서 확인되는 핵심 현상을 간결하게 보여드립니다.</p>${newsGuide}</header><div class="jcs-diagnostics-public-grid">${topics.map(renderPublicDiagnostic).join('')}</div><footer><button type="button" class="primary-btn" data-layout-route="/login">로그인하고 상세 분석 보기</button></footer></section>`;}

export async function renderPoliticianDetail(id,service,session=null){
  const result=await service.get(id);if(!result?.ok)return `<main class="subpage"><section class="content-card empty-state tall"><div class="empty-icon">?</div><h2>존재하지 않는 정치인입니다</h2><button class="primary-btn" type="button" data-layout-route="/now">전체 정치인</button></section></main>`;
  const sourceItem=result.item,published=result.intelligence||null,pilot=published,item=pilot?.currentRole?{...sourceItem,office:pilot.currentRole}:sourceItem,activityTitle=item.type==='assembly'?'의정활동':'행정활동',photo=photoMarkup(item,'person-detail-photo',384).replace('loading="lazy"','loading="eager"'),photoSource=item.photo?.sourcePage?` · 사진 출처: ${esc(item.photo.sourcePage)}`:'';
  const rankLabel=value=>Number.isFinite(Number(value))&&Number(value)>0?`${Number(value)}위`:'집계 전';
  const rank=`<div class="person-hero-now person-hero-rank-split ${pilot?'':'is-empty'}" aria-label="NOW 순위"><div class="person-hero-rank-cell"><span>전체 NOW</span><strong>${rankLabel(pilot?.rank?.overall)}</strong></div><div class="person-hero-rank-cell"><span>${esc(TYPES[item.type]?.label||'분야별 NOW')}</span><strong>${rankLabel(pilot?.rank?.category)}</strong></div><div class="person-hero-rank-trend"><span class="person-rank-status">순위 유지</span></div></div>`;
  const isLegacyPilot=!!pilot&&!published,hasRecords=Array.isArray(pilot?.activities)&&pilot.activities.length,activities=hasRecords?`<dl class="info-list"><div><dt>${item.type==='assembly'?'소속 위원회':'관할 지역'}</dt><dd>${value(item.type==='assembly'?item.committee:item.jurisdiction)}</dd></div><div><dt>주요 활동</dt><dd>${pilot.activities.map(esc).join('<br>')}</dd></div><div><dt>주요 성과</dt><dd>${(pilot.achievements||[]).map(esc).join('<br>')||empty()}</dd></div></dl>`:`<dl class="info-list"><div><dt>${item.type==='assembly'?'소속 위원회':'관할 지역'}</dt><dd>${value(item.type==='assembly'?item.committee:item.jurisdiction)}</dd></div><div><dt>주요 활동</dt><dd>${empty()}</dd></div><div><dt>주요 성과</dt><dd>${empty()}</dd></div></dl>`;
  const policies=Array.isArray(pilot?.policies)&&pilot.policies.length?`<div class="person-policy-list">${pilot.policies.map((x,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><b>${esc(x)}</b></article>`).join('')}</div>`:'<div class="person-news-empty">연결된 공식 프로필에 공약·정책 기록이 없습니다.</div>';
  const notice=published?`<section class="content-card"><div class="notice-box"><b>${esc(item.name)} 공개 인텔리전스 · ${esc(published.snapshot)}</b><br>네이버 검색광고·Google 뉴스·공식 프로필·선거 및 인구 공개자료와 JCS 해석을 구분해 적용했습니다. 원자료 수치는 그대로 보존하고 지표·진단·전략은 정참시 해석값으로 표시합니다.<br>기본 텍스트 출처: ${esc(item.source||'기존 정참시 공식 프로필')}${photoSource}</div></section>`:pilot?`<section class="content-card"><div class="notice-box"><b>김민석 단일 파일럿 · ${esc(pilot.snapshot)}</b><br>공식 선거·경선 결과, 한국갤럽, Google 뉴스 중심 공개자료와 정참시 분석값을 구분해 적용했습니다. 연령×성별과 분석 점수는 후보 개인의 실측 지지율이 아니라 출처 자료를 재구성한 비교지수입니다. 네이버 검색광고는 API 키 준비 전이므로 수치 생성·대체·fallback 없이 이번 산정에서 제외했습니다.<br>기본 텍스트 출처: ${esc(item.source||'기존 정참시 공식 프로필')}${photoSource}</div></section>`:`<section class="content-card"><div class="notice-box">현재 연결된 실제 정보는 공식 프로필·정치 기록과 사진뿐입니다. 분석·순위·뉴스·추천·관리자 인텔리전스는 레이아웃만 복원했으며 값은 가져오지 않았습니다.<br>기본 텍스트 출처: ${esc(item.source||'기존 정참시 공식 프로필')}${photoSource}</div></section>`;
  return `<main class="subpage person-live-detail-page jcs-public-intelligence-v3" data-recent-politician data-recent-id="${esc(item.id)}" data-recent-name="${esc(item.name)}" data-recent-party="${esc(item.party)}" data-recent-office="${esc(item.office||item.roleLabel)}" data-recent-photo="${esc(item.photo?.localPath||'')}" data-recent-focus="${esc(item.photo?.focus||'50% 28%')}"><section class="person-detail-hero person-live-hero content-card">${photo}<div class="person-detail-title"><span class="eyebrow">${esc(item.roleLabel)} · LIVE PROFILE</span><h1>${esc(item.name)}</h1><p class="person-current-role">${esc(item.office||item.roleLabel)}</p><p>${esc([item.party,item.jurisdiction].filter(Boolean).join(' · '))}</p><div class="person-detail-badges"><span>${esc(item.roleLabel)}</span><span>${esc(item.terms||'기본정보')}</span><span>${esc(item.type==='assembly'?(item.committee||'국회의원'):item.jurisdiction)}</span></div></div>${rank}<div class="detail-action-bar"><button class="ghost-btn" type="button" data-layout-route="/now?type=${esc(item.type)}">목록으로</button><button class="ghost-btn" type="button" disabled>즐겨찾기 준비 중</button><button class="ghost-btn" type="button" data-layout-route="/compare?ids=${esc(item.id)}">비교하기</button></div></section>${roleDiagnostics(published,item)}${Array.isArray(pilot?.news)&&pilot.news.length?pilotNews(pilot):newsShell()}<section class="person-profile-divider"><span>PROFILE & RECORD</span><b>공식 프로필과 정치 기록</b></section><div class="detail-grid"><section class="content-card"><div class="section-title"><h2>기본정보</h2><span>공개 프로필</span></div>${basicInfo(item)}</section><section class="content-card"><div class="section-title"><h2>임기 · 선거정보</h2><span>공식 기록</span></div>${electionInfo(item)}</section></div><section class="content-card"><div class="section-title"><h2>정치 타임라인</h2><span>${pilot?'공식 기록 + 최신 공개자료':'기존 공식 프로필 기록'}</span></div><div class="timeline-shell">${timeline(item)}${isLegacyPilot?`<div class="timeline-row live"><span class="timeline-year">2026</span><div class="timeline-copy"><b>더불어민주당 대표 선출</b><span>최종 54.08% · 임기 2년</span></div></div>`:''}</div></section><section class="content-card"><div class="section-title"><h2>${activityTitle}</h2><span>${published?'공식 기록 + 공개 분석':'공식 프로필 범위'}</span></div>${activities}</section><section class="content-card"><div class="section-title"><h2>공약 · 정책</h2><span>${pilot?'최근 공개 메시지 기준':'공식 프로필 범위'}</span></div>${policies}</section>${Array.isArray(pilot?.related)&&pilot.related.length?pilotRelated(pilot):relatedShell()}${strategicConsulting()}${notice}</main>`;
}
